data":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true}}},{"id":"tagum_2026_2027_shs_g12_newton","parent_id":"tagum_2026_2027_shs_g12_group4","data":{"id":"tagum_2026_2027_shs_g12_newton","name":"Newton","type":"section","metadata":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true}}},{"id":"tagum_2026_2027_shs_g12_group5","parent_id":"tagum_2026_2027_shs_g12","data":{"id":"tagum_2026_2027_shs_g12_group5","name":"TVL–ICT","type":"strand","metadata":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true,"allowedChildTypes":["section"]}}},{"id":"tagum_2026_2027_shs_g12_faraday","parent_id":"tagum_2026_2027_shs_g12_group5","data":{"id":"tagum_2026_2027_shs_g12_faraday","name":"Faraday","type":"section","metadata":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true}}},{"id":"tagum_2026_2027_shs_g12_group6","parent_id":"tagum_2026_2027_shs_g12","data":{"id":"tagum_2026_2027_shs_g12_group6","name":"TVL–HE","type":"strand","metadata":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true,"allowedChildTypes":["section"]}}},{"id":"tagum_2026_2027_shs_g12_mendeleev","parent_id":"tagum_2026_2027_shs_g12_group6","data":{"id":"tagum_2026_2027_shs_g12_mendeleev","name":"Mendeleev","type":"section","metadata":{"schemaVersion":2,"academicYear":"2026-2027","selectableForEvents":true,"selectableForRegistration":true}}}]'::jsonb;
begin
  if not exists (select 1 from public.rmc_profiles where id = auth.uid()
    and role_id = 'admin' and status = 'active') then
    raise exception 'Import requires a verified active administrator context';
  end if;
  select id into strict campus_id from public.rmc_nodes
  where parent_id is null and data->>'name' = 'Rizal Memorial Colleges, Inc., Tagum Campus';
  for item in select value from jsonb_array_elements(expected) loop
    parent := coalesce(item->>'parent_id', campus_id);
    if exists (select 1 from public.rmc_nodes where parent_id = parent
      and lower(data->>'name') = lower(item#>>'{data,name}') and id <> item->>'id') then
      raise exception 'Existing matching unit requires reconciliation: %', item#>>'{data,name}';
    end if;
    if exists (select 1 from public.rmc_nodes where id = item->>'id'
      and (parent_id is distinct from parent or data->>'name' is distinct from item#>>'{data,name}'
        or data->>'type' is distinct from item#>>'{data,type}'
        or data#>>'{metadata,archived}' = 'true')) then
      raise exception 'Conflicting or archived import ID: %', item->>'id';
    end if;
    insert into public.rmc_nodes (id, parent_id, data)
    values (item->>'id', parent, item->'data') on conflict (id) do nothing;
  end loop;
  if (select count(*) from public.rmc_nodes n join jsonb_array_elements(expected) e
    on n.id = e->>'id' where n.data->>'type' = 'section') <> 33 then
    raise exception 'Expected 33 imported sections';
  end if;
end;
$import$;
commit;

-- Independent readback for verification after the transaction.
select id, parent_id, data->>'name' as name, data->>'type' as type,
  data->'metadata' as metadata from public.rmc_nodes
where starts_with(id, 'tagum_2026_2027_') order by id;
